@page "/dashboard"
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="card mt-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">
            <span class="bi bi-exclamation-triangle-fill text-warning me-2"></span>
            Low-Stock Alerts
        </h5>
        <p class="display-4 text-danger">@AlertService.LowStockCount</p>
        <p class="text-muted mb-0">
            Items below minimum level. Refreshes every 10 seconds.
        </p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertDataChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when this page becomes visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;

        // Stop polling when user leaves this page
        AlertService.StopPolling();
    }
}

